  ('trees', 'barangay'),
  ('trees', 'barangay_psgc'),
  ('trees', 'municipality'),
  ('trees', 'species'),
  ('trees', 'scientific_name'),
  ('trees', 'species_type'),
  ('trees', 'biodiversity_status'),
  ('trees', 'tree_category'),
  ('trees', 'dbh'),
  ('trees', 'merchantable_height'),
