  ('trees', 'stem_quality'),
  ('trees', 'isLeaning'),
  ('trees', 'hasPowerlineConflict'),
  ('trees', 'isRootProblem'),
  ('trees', 'isDecayed'),
  ('trees', 'assigned_to'),
  ('trees', 'has_cutting_permit'),
  ('trees', 'task_status'),
  ('trees', 'source'),
